                    if (numPilihan > (totalPilihan - 1)) {
                        numPilihan = 0;
                    }

                    var titlePilihan = $('.queues-' + numPilihan).attr('data-title');
                    var urlPilihan = $('.queues-' + numPilihan).attr('data-url');
                    var textPilihan = `
                        <a href="`+ urlPilihan +`">
                            <div class="breaking-news">
                                <div class="title-breaking">
                                    `+ titlePilihan +`
                                </div>
                                <div class="btn-more-breaking">
                                    Lihat Selengkapnya <i class="fas fa-chevron-right"></i>
                                </div>
                            </div>
                        </a>`;

                        $('.breaking-news-placement').empty().append(textPilihan);
                    numPilihan++;
                }, 7000);
                
                function bottomStickyAd(mbmin){
                    $('.center-fclose').clickToggle(function() {
                        $('.center-float-large').addClass(mbmin).removeClass('mb0').addClass('clicked');
                        $('.up').show();
                        $('.down').hide();
                    }, function() {
                        $('.center-float-large').removeClass(mbmin).addClass('mb0').removeClass('clicked');
                        $('.up').hide();
                        $('.down').show();
                    });

                    $(window).scroll(function() {
                        if (($(window).scrollTop() + $(window).height()) >= ($(document).height() - 600)) {
                            $('.center-float-large').addClass(mbmin).removeClass('mb0');
                            $('.up').show();
                            $('.down').hide();
                        } else {
                            if (!$('.center-float-large').hasClass('clicked')) {
                                $('.center-float-large').removeClass(mbmin).addClass('mb0');
                                $('.up').hide();
                                $('.down').show();
                            }
                        }
                    });
                }
                
